import Foundation
final class UnitSettings: NSObject {
    @objc dynamic func title() -> NSString { "Сантиметры" }
}
let state = UnitSettings()
let selector = #selector(UnitSettings.title)
if state.responds(to: selector) {
    let value = state.perform(selector)?.takeUnretainedValue()
    print(value as? NSString ?? "Нет единицы")
}

Вывод: Сантиметры. Проверка наличия дополняет известную совместимую сигнатуру, но не заменяет её.

