import Foundation
final class Thermostat: NSObject {
    @objc dynamic var temperature = 18
}
final class TemperatureScreen {
    let model = Thermostat()
    var token: NSKeyValueObservation?
    var text = "18"
    func start() {
        token?.invalidate()
        token = model.observe(\.temperature, options: [.new]) {
            [weak self] _, change in
            self?.text = String(change.newValue ?? 0)
        }
    }
    func stop() { token?.invalidate(); token = nil }
}
var screen: TemperatureScreen? = TemperatureScreen()
weak var observedScreen = screen
screen?.start()
screen?.model.temperature = 22
print(screen?.text ?? "Нет экрана")
screen = nil
print(observedScreen == nil)

Вывод: 22, true. Экран удерживает токен, токен удерживает callback, поэтому сильный self создавал цикл. weak-захват освобождает экран без принудительного stop.

