import Foundation
final class StrokeSettings: NSObject {
    @objc dynamic var strokeWidth = 14
}
let settings = StrokeSettings()
let path = \StrokeSettings.strokeWidth
settings[keyPath: path] = 18
print(settings[keyPath: path])

Вывод: 18. Swift key path проверяется компилятором и сохраняет тип Int; KVC по строке нужен только там, где API действительно принимает строковый ключ. Для известного свойства #keyPath тоже убрал бы опечатку, но результат value(forKey:) остался бы нетипизированным.
